code.python:
class Solution:
    def isPerfectSquare(self, tiles: int) -> bool:
        lo, hi = 1, min(tiles, 10**8)
        while lo <= hi:
            mid = (lo + hi) // 2
            sq = mid * mid
            if sq == tiles:
                return True
            if sq < tiles:
                lo = mid + 1
            else:
                hi = mid - 1
        return False

code.java:
class Solution {
    public boolean isPerfectSquare(long tiles) {
        long lo = 1, hi = Math.min(tiles, 100_000_000L);
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            long sq = mid * mid;
            if (sq == tiles) return true;
            if (sq < tiles) lo = mid + 1;
            else hi = mid - 1;
        }
        return false;
    }
}

